CREATE OR REPLACE FUNCTION public.mark_new_vehicle_plan() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.vehicle_plan_months:=1; RETURN NEW; END $$;
COMMENT ON COLUMN public.membership_requests.vehicle_plan_months IS 'One calendar month for new requests; administrator-approved historical receipts retained as evidence.';
CREATE OR REPLACE FUNCTION public.review_membership_evidence(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.membership_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO r FROM public.membership_requests WHERE id=_id FOR UPDATE; IF r.id IS NULL OR r.status<>'pending' THEN RAISE EXCEPTION 'REVIEW_REQUIRED'; END IF; UPDATE public.membership_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,reviewed_at=now(),reviewed_by=auth.uid(),vehicle_plan_months=1 WHERE id=_id; UPDATE public.membership_access SET source=CASE WHEN _approve THEN 'confirmed' ELSE source END,starts_at=CASE WHEN _approve THEN now() ELSE starts_at END,ends_at=CASE WHEN _approve THEN now()+interval '1 month' ELSE ends_at END,revoked_at=CASE WHEN _approve THEN NULL ELSE now() END,granted_by=auth.uid() WHERE request_id=_id; IF _approve AND r.payer_id=r.user_id THEN PERFORM public.confirm_referral_cash(r.user_id,r.reference,r.amount::bigint*100); END IF; INSERT INTO public.messages(sender_id,receiver_id,body,is_auto) VALUES(auth.uid(),r.user_id,CASE WHEN _approve THEN 'మీ చెల్లింపును నిర్వాహకులు ఆమోదించారు. మీ చందా ప్రారంభమైంది; ఇప్పటి నుంచి ఒక నెల పూర్తి వివరాలు చూడవచ్చు.' ELSE 'మీ చెల్లింపు నిర్ధారణ కాలేదు. అడ్మిన్ తో చాట్ చేయండి.' END,true); END $$;
REVOKE ALL ON FUNCTION public.review_membership_evidence(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.review_membership_evidence(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.post_listing_visible(p public.posts,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT p.status='active' AND (p.visible_after IS NULL OR p.visible_after<=_at) AND (p.job_expires_at IS NULL OR p.job_expires_at>_at) AND CASE WHEN p.module='job' THEN p.created_at+interval '30 days'>_at WHEN p.module='vehicle' THEN CASE WHEN lower(trim(coalesce(p.vehicle_type,''))) NOT IN('car','innova','swift dzire','ertiga','bolero','sedan','suv','hatchback') AND trim(coalesce(p.from_place,''))<>'' AND lower(trim(p.from_place))=lower(trim(coalesce(p.to_place,''))) THEN p.created_at+interval '1 day'>_at ELSE p.trip_date IS NOT NULL AND p.trip_date>=(_at AT TIME ZONE 'Asia/Kolkata')::date END ELSE true END $$;
GRANT EXECUTE ON FUNCTION public.post_listing_visible(public.posts,timestamptz) TO anon,authenticated,service_role;
CREATE POLICY listing_expiry_preserves_owner_history ON public.posts AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.post_listing_visible(posts));
CREATE OR REPLACE FUNCTION public.list_anonymous_bell_board(_section text) RETURNS TABLE(id uuid,source text,area text,need text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF; IF _section IN('goods','returns','cars') THEN IF NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN QUERY SELECT d.id,'vehicle'::text,d.from_place||' → '||d.to_place,d.vehicle_type FROM public.vehicle_bell_demands d WHERE d.category=_section AND public.account_allowed(d.user_id) AND (d.post_id IS NULL OR EXISTS(SELECT 1 FROM public.posts p WHERE p.id=d.post_id AND public.post_listing_visible(p))) AND (_section<>'goods' OR d.rang_at+interval '1 day'>now()) ORDER BY d.rang_at DESC; ELSE RETURN QUERY SELECT i.id,'post'::text,i.area,i.need FROM public.post_bell_interests i WHERE i.section=_section AND public.account_allowed(i.user_id) AND i.created_at+interval '30 days'>now() AND (NOT EXISTS(SELECT 1 FROM public.posts p WHERE p.id=i.post_id) OR EXISTS(SELECT 1 FROM public.posts p WHERE p.id=i.post_id AND public.post_listing_visible(p))) ORDER BY i.created_at DESC; IF _section='service-providers' THEN RETURN QUERY SELECT r.id,'service'::text,r.area,r.service FROM public.service_requests r WHERE public.account_allowed(r.user_id) AND r.created_at+interval '30 days'>now() ORDER BY r.created_at DESC; END IF; END IF; END $$;
REVOKE ALL ON FUNCTION public.list_anonymous_bell_board(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.list_anonymous_bell_board(text) TO authenticated;